// Generated by `just generate` from `src/plugins/dotclaude/slices/statusline/width.ts`. Edit the source and run `just generate`.
// The width of text in terminal columns, and a cut to a width.
// An escape sequence has no width. A wide character, such as an emoji or a CJK character, has two columns.

import { ICON } from "./icons.ts";

const ESC = String.fromCharCode(27);
const ESCAPE = new RegExp(`${ESC}\\[[0-9;]*m`, "g");
const SEQUENCE = new RegExp(`^${ESC}\\[[0-9;]*m$`);
const SPLIT = new RegExp(`(${ESC}\\[[0-9;]*m)`);

/** The text without its color sequences. */
export const plainText = (text: string): string => text.replace(ESCAPE, "");

/**
 * The code points below U+10000 with default emoji presentation (`Emoji_Presentation`), as ranges.
 * Each one takes two columns. A symbol with text presentation, such as `✎` or `◷`, is not here and takes one.
 */
const EMOJI_RANGES: readonly (readonly [number, number])[] = [
  [0x231a, 0x231b],
  [0x23e9, 0x23ec],
  [0x23f0, 0x23f0],
  [0x23f3, 0x23f3],
  [0x25fd, 0x25fe],
  [0x2614, 0x2615],
  [0x2648, 0x2653],
  [0x267f, 0x267f],
  [0x2693, 0x2693],
  [0x26a1, 0x26a1],
  [0x26aa, 0x26ab],
  [0x26bd, 0x26be],
  [0x26c4, 0x26c5],
  [0x26ce, 0x26ce],
  [0x26d4, 0x26d4],
  [0x26ea, 0x26ea],
  [0x26f2, 0x26f3],
  [0x26f5, 0x26f5],
  [0x26fa, 0x26fa],
  [0x26fd, 0x26fd],
  [0x2705, 0x2705],
  [0x270a, 0x270b],
  [0x2728, 0x2728],
  [0x274c, 0x274c],
  [0x274e, 0x274e],
  [0x2753, 0x2755],
  [0x2757, 0x2757],
  [0x2795, 0x2797],
  [0x27b0, 0x27b0],
  [0x27bf, 0x27bf],
  [0x2b1b, 0x2b1c],
  [0x2b50, 0x2b50],
  [0x2b55, 0x2b55],
];

const isEmoji = (code: number): boolean =>
  EMOJI_RANGES.some(([low, high]) => code >= low && code <= high);

const isWide = (code: number): boolean =>
  isEmoji(code) ||
  (code >= 0x1100 && code <= 0x115f) ||
  (code >= 0x2e80 && code <= 0xa4cf) ||
  (code >= 0xac00 && code <= 0xd7a3) ||
  (code >= 0xf900 && code <= 0xfaff) ||
  (code >= 0xfe30 && code <= 0xfe6f) ||
  (code >= 0xff00 && code <= 0xff60) ||
  (code >= 0xffe0 && code <= 0xffe6) ||
  (code >= 0x1f300 && code <= 0x1faff) ||
  (code >= 0x20000 && code <= 0x3fffd);

const isZero = (code: number): boolean =>
  (code >= 0x300 && code <= 0x36f) ||
  code === 0x200d ||
  (code >= 0xfe00 && code <= 0xfe0f);

/** The columns of one character. */
const columnsOf = (char: string): number => {
  const code = char.codePointAt(0) ?? 0;
  if (isZero(code)) return 0;
  return isWide(code) ? 2 : 1;
};

/** The columns that `text` takes, with its color sequences not counted. */
export const width = (text: string): number => {
  let columns = 0;
  for (const char of plainText(text)) columns += columnsOf(char);
  return columns;
};

/**
 * `text` cut to at most `max` columns, with `…` as its last character when it is cut.
 * A color sequence in the kept part stays, and a reset sequence closes the cut text, so no color leaks.
 */
export const truncate = (text: string, max: number): string => {
  if (width(text) <= max) return text;
  if (max <= 0) return "";
  let out = "";
  let columns = 0;
  let colored = false;
  for (const part of text.split(SPLIT)) {
    if (SEQUENCE.test(part)) {
      out += part;
      colored = part !== "\u001b[0m";
      continue;
    }
    for (const char of part) {
      const next = columnsOf(char);
      if (columns + next > max - 1)
        return `${out}${ICON.ellipsis}${colored ? "\u001b[0m" : ""}`;
      out += char;
      columns += next;
    }
  }
  return out;
};
